package Perl::Critic::Policy::ElegantPerl::NoCustomConstructor;

use v5.32;
use strict;
use warnings;

use parent 'Elegant::Perl::Critic::Policy';


my $EXPLANATION =
    'new() is generated by Elegant::Perl. '
    . 'Constructors contain no application logic.';


sub violations_for {
    my ($self, $document) = @_;

    my @violations;

    my $subs =
        $document->find(
            'PPI::Statement::Sub'
        ) || [];


    for my $sub (@$subs) {
        next
            unless ($sub->name // '')
                eq 'new';


        push @violations,
            $self->violation(
                'Custom new() is forbidden',
                $EXPLANATION,
                $sub,
            );
    }


    return @violations;
}


1;